insert into public.events (
  id, title, description, category, price, start_time, end_time, address,
  latitude, longitude, capacity, image_url, is_group_activity, is_outdoor, source_url
)
values
  ('00000000-0000-4000-8000-000000000021', 'Burnaby Lake Loop Walk', 'Walk the flat trails around Burnaby Lake and look for herons, ducks, and beavers.', 'outdoors', 0, null, null, 'Burnaby Lake Regional Park, 4519 Piper Avenue, Burnaby, BC', 49.2427, -122.9643, 20, 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=900&q=80', true, true, 'https://metrovancouver.org/services/burnaby-lake-regional-park'),
  ('00000000-0000-4000-8000-000000000022', 'Burnaby Mountain Sunset Viewpoint', 'Take in Burrard Inlet and the North Shore mountains from the Kamui Mintara lookout.', 'outdoors', 0, null, null, 'Burnaby Mountain Park, 100 Centennial Way, Burnaby, BC', 49.2804, -122.9276, 20, 'https://images.unsplash.com/photo-1500534623283-312aade485b7?auto=format&fit=crop&w=900&q=80', false, true, 'https://www.burnaby.ca/explore-outdoors/parks/burnaby-mountain-park'),
  ('00000000-0000-4000-8000-000000000023', 'Deer Lake Park Picnic', 'Bring a coffee or picnic and explore the lake loop, pier, and surrounding gardens.', 'outdoors', 0, null, null, 'Deer Lake Park, 5435 Sperling Avenue, Burnaby, BC', 49.2315, -122.9591, 12, 'https://images.unsplash.com/photo-1473448912268-2022ce9509d8?auto=format&fit=crop&w=900&q=80', false, true, 'https://www.burnaby.ca/explore-outdoors/parks/deer-lake-park'),
  ('00000000-0000-4000-8000-000000000024', 'Burnaby Village Museum Visit', 'Explore the recreated heritage village, historic buildings, and restored C.W. Parker Carousel.', 'culture', 0, null, null, 'Burnaby Village Museum, 6501 Deer Lake Avenue, Burnaby, BC', 49.2381, -122.9706, 40, 'https://images.unsplash.com/photo-1561214115-f2f134cc4912?auto=format&fit=crop&w=900&q=80', false, false, 'https://www.burnabyvillagemuseum.ca/'),
  ('00000000-0000-4000-8000-000000000025', 'Central Park Forest Run', 'Run or walk the quiet trails around Central Park and finish near the Swangard Stadium area.', 'fitness', 0, null, null, 'Central Park, 3883 Imperial Street, Burnaby, BC', 49.2267, -123.0225, 20, 'https://images.unsplash.com/photo-1552674605-db6ffd4facb5?auto=format&fit=crop&w=900&q=80', true, true, 'https://www.burnaby.ca/explore-outdoors/parks/central-park'),
  ('00000000-0000-4000-8000-000000000026', 'Buntzen Lake Trail Day', 'Spend the day on the Buntzen Lake loop and nearby forest trails in Anmore.', 'outdoors', 0, null, null, 'Buntzen Lake Recreation Area, Anmore, BC', 49.3647, -122.8581, 18, 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=900&q=80', true, true, 'https://bcparks.ca/buntzen-lake-park/'),
  ('00000000-0000-4000-8000-000000000027', 'Climb at Hive Heights', 'Try bouldering and rope climbing at a local gym near Brentwood.', 'fitness', 28, null, null, 'The Hive Heights, 520 Industrial Avenue, Vancouver, BC', 49.2696, -123.0027, 16, 'https://images.unsplash.com/photo-1522163182402-834f871fd851?auto=format&fit=crop&w=900&q=80', true, false, 'https://thehiveclimbing.com/locations/heights/'),
  ('00000000-0000-4000-8000-000000000028', 'Cafe Study Session at Prototype', 'Grab a coffee and spend an hour reading or working in a relaxed Mount Pleasant cafe.', 'food', 8, null, null, 'Prototype Coffee, 883 East Hastings Street, Vancouver, BC', 49.2812, -123.0892, 8, 'https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=900&q=80', false, false, 'https://prototype-coffee.com/'),
  ('00000000-0000-4000-8000-000000000029', 'Morning Run at Rocky Point', 'Run the waterfront path, watch the boats, and explore Port Moody breweries afterward.', 'fitness', 0, null, null, 'Rocky Point Park, 2800 Murray Street, Port Moody, BC', 49.2772, -122.8613, 20, 'https://images.unsplash.com/photo-1476480862126-209bfaa8edc8?auto=format&fit=crop&w=900&q=80', true, true, 'https://www.portmoody.ca/en/recreation-parks-and-environment/rocky-point-park.aspx'),
  ('00000000-0000-4000-8000-000000000030', 'Museum of Anthropology Afternoon', 'See Northwest Coast Indigenous art and architecture at the museum on the SFU-area campus.', 'culture', 26, null, null, 'Museum of Anthropology, 6393 NW Marine Drive, Vancouver, BC', 49.2696, -123.2580, 40, 'https://images.unsplash.com/photo-1564399579883-451a5d44ec08?auto=format&fit=crop&w=900&q=80', false, false, 'https://moa.ubc.ca/'),
  ('00000000-0000-4000-8000-000000000031', 'Burnaby Lake Sunset Run', 'A casual group run on the trails near Piper Avenue, suitable for multiple paces.', 'fitness', 0, '2026-10-09T01:00:00Z', '2026-10-09T02:30:00Z', 'Burnaby Lake Regional Park, 4519 Piper Avenue, Burnaby, BC', 49.2427, -122.9643, 24, 'https://images.unsplash.com/photo-1552674605-db6ffd4facb5?auto=format&fit=crop&w=900&q=80', true, true, 'https://lifemaxxing.local/sfu/burnaby-lake-sunset-run-2026-10-08'),
  ('00000000-0000-4000-8000-000000000032', 'Deer Lake Photography Walk', 'Meet other beginners for a relaxed golden-hour photo walk around Deer Lake.', 'art', 0, '2026-10-11T00:30:00Z', '2026-10-11T02:30:00Z', 'Deer Lake Park, 5435 Sperling Avenue, Burnaby, BC', 49.2315, -122.9591, 16, 'https://images.unsplash.com/photo-1452587925148-ce544e77e70d?auto=format&fit=crop&w=900&q=80', true, true, 'https://lifemaxxing.local/sfu/deer-lake-photography-2026-10-10'),
  ('00000000-0000-4000-8000-000000000033', 'Burnaby Mountain Stargazing', 'Bring a warm layer and discover the best viewpoints for a clear evening sky.', 'outdoors', 0, '2026-10-14T03:00:00Z', '2026-10-14T05:00:00Z', 'Burnaby Mountain Park, 100 Centennial Way, Burnaby, BC', 49.2804, -122.9276, 25, 'https://images.unsplash.com/photo-1462331940025-496dfbfc7564?auto=format&fit=crop&w=900&q=80', true, true, 'https://lifemaxxing.local/sfu/burnaby-mountain-stargazing-2026-10-13'),
  ('00000000-0000-4000-8000-000000000034', 'Port Moody Brewery Walk', 'Walk the Brewers Row trail and sample a few local non-alcoholic or alcoholic options.', 'food', 25, '2026-10-16T01:00:00Z', '2026-10-16T03:30:00Z', 'Murray Street, Port Moody, BC', 49.2775, -122.8623, 14, 'https://images.unsplash.com/photo-1515003197210-e0cd71810b5f?auto=format&fit=crop&w=900&q=80', true, false, 'https://lifemaxxing.local/sfu/port-moody-brewery-walk-2026-10-15'),
  ('00000000-0000-4000-8000-000000000035', 'Lynn Canyon Forest Hike', 'A moderate forest hike through old-growth trees and across the suspension bridge.', 'outdoors', 0, '2026-10-18T16:00:00Z', '2026-10-18T20:00:00Z', 'Lynn Canyon Park, 3663 Park Road, North Vancouver, BC', 49.3436, -123.0229, 12, 'https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=900&q=80', true, true, 'https://lynncanyon.ca/'),
  ('00000000-0000-4000-8000-000000000036', 'Granville Island Market Trip', 'Browse local produce, baked goods, and artisan stalls with a small social group.', 'food', 15, '2026-10-20T18:00:00Z', '2026-10-20T20:30:00Z', 'Granville Island Public Market, 1689 Johnston Street, Vancouver, BC', 49.2712, -123.1340, 16, 'https://images.unsplash.com/photo-1488459716781-31db?auto=format&fit=crop&w=900&q=80', true, false, 'https://granvilleisland.com/directory/public-market'),
  ('00000000-0000-4000-8000-000000000037', 'Science World Evening Visit', 'Explore hands-on exhibits and the dome theatre at the False Creek waterfront.', 'culture', 34, '2026-10-23T01:00:00Z', '2026-10-23T03:30:00Z', 'Science World, 1455 Quebec Street, Vancouver, BC', 49.2734, -123.1036, 30, 'https://images.unsplash.com/photo-1532094349884-543bc11b234d?auto=format&fit=crop&w=900&q=80', false, false, 'https://www.scienceworld.ca/'),
  ('00000000-0000-4000-8000-000000000038', 'Grouse Mountain Trail Day', 'Take the gondola or hike the Grouse Grind, then enjoy the mountain viewpoints.', 'outdoors', 75, '2026-10-25T16:00:00Z', '2026-10-25T22:00:00Z', 'Grouse Mountain, 6400 Nancy Greene Way, North Vancouver, BC', 49.3728, -123.0985, 20, 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=900&q=80', true, true, 'https://www.grousemountain.com/'),
  ('00000000-0000-4000-8000-000000000039', 'Central Park Volunteer Cleanup', 'Help collect litter and care for trails during a community park morning.', 'volunteering', 0, '2026-10-27T16:00:00Z', '2026-10-27T18:00:00Z', 'Central Park, 3883 Imperial Street, Burnaby, BC', 49.2267, -123.0225, 30, 'https://images.unsplash.com/photo-1559027615-cd4628902d4a?auto=format&fit=crop&w=900&q=80', true, true, 'https://lifemaxxing.local/sfu/central-park-cleanup-2026-10-27')
on conflict (id) do update set
  title = excluded.title,
  description = excluded.description,
  category = excluded.category,
  price = excluded.price,
  start_time = excluded.start_time,
  end_time = excluded.end_time,
  address = excluded.address,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  capacity = excluded.capacity,
  image_url = excluded.image_url,
  is_group_activity = excluded.is_group_activity,
  is_outdoor = excluded.is_outdoor,
  source_url = excluded.source_url;
